args <- commandArgs(trailingOnly=TRUE); root <- if(length(args)) normalizePath(args[1],mustWork=TRUE) else normalizePath('.',mustWork=TRUE)
r <- function(p) read.csv(p,stringsAsFactors=FALSE,check.names=FALSE,na.strings='')
a<-r(file.path(root,'data/processed/scenarios/ecology_scenario_assumptions.csv')); n<-r(file.path(root,'data/processed/scenarios/ecology_nodes_scenario.csv')); e<-r(file.path(root,'data/processed/scenarios/ecology_edges_scenario.csv')); d<-r(file.path(root,'data/processed/scenarios/ecological_disturbance_scenario.csv')); q<-r(file.path(root,'data/processed/scenarios/ecological_resilience_scenario.csv')); c<-r(file.path(root,'outputs/figures/ecological_scenarios_comparison.csv'))
states<-c('A2050','A2075','B2050','B2075','C2050','C2075'); comps<-c('western_lake_erie_aquatic','maumee_tributary_floodplain','coastal_wetlands_marshes','black_swamp_legacy_agriculture','terrestrial_habitat_fragmentation','migratory_mobile_species')
stopifnot(nrow(a)==18,nrow(n)==36,nrow(e)==30,nrow(d)==36,nrow(q)==36,nrow(c)==72); stopifnot(all(unique(a$scenario_id)%in%states),all(unique(n$scenario_id)%in%states),all(unique(c$scenario_id)%in%states)); stopifnot(all(table(a$scenario_id)==3),all(table(n$scenario_id)==6),all(table(e$scenario_id)==5),all(table(d$scenario_id)==6),all(table(q$scenario_id)==6),all(table(c$scenario_id)==12)); stopifnot(all(unique(n$ecological_component)%in%comps),all(n$reality_status=='fictional'),all(n$relationship_basis=='scenario_assumption')); stopifnot(all(a$plausibility%in%c('high','moderate','exploratory')),all(c$level%in%c('low','moderate','high')))
t<-paste(a$assumption,n$notes,e$notes,d$notes,q$notes,c$notes,collapse=' '); stopifnot(!grepl('extinction|malaria|arbovirus|mosquito transmission|exact (migration|animal|flight|spawning) route|precise (nest|roost|den|spawning) location',t,ignore.case=TRUE)); stopifnot(!grepl('Great Black Swamp.{0,100}(polygon|boundary)',t,ignore.case=TRUE)); stopifnot(file.exists(file.path(root,'outputs/maps/systems/22_ecological_futures_2050.png')),file.exists(file.path(root,'outputs/maps/systems/22b_ecological_futures_2075.png')))
cat('R Phase 6C ecological-scenario validation passed: 18 assumptions, 36 nodes, 30 edges, 36 disturbance states, 36 resilience states, 72 comparison rows\n')
